/**
 * Builds the base64 text for given bytes, using settings of given variant.
 *<p>
 * Input is consumed from the start in groups of three bytes; when fewer than
 * three bytes remain, the last group holds the remaining one or two bytes.
 * For each group, the group value is obtained from
 * {@link ByteArrayBuilder#packGroup} (with the group's start index and byte
 * count) and passed, together with the byte count, to
 * {@link CharTypes#appendBase64Group}, which appends the characters.
 *<p>
 * Line splitting: a counter starts at {@code variant.getMaxLineLength() >> 2};
 * it is decremented after each complete (three-byte) group, and whenever it
 * reaches zero or less, an escaped linefeed (a backslash followed by 'n', as
 * needed within a JSON String value) is appended and the counter starts over.
 * The final one- or two-byte group never adds a linefeed.
 *<p>
 * If {@code addQuotes} is true, the text is enclosed in double quotes.
 *
 * @param variant Variant whose alphabet, padding and line length are used
 * @param input Bytes to convert
 * @param addQuotes Whether to surround the text in double quotes
 *
 * @return Text built as described above
 */
public static String encodeToText(Base64Variant variant, byte[] input, boolean addQuotes)
{
    final int inputEnd = input.length;
    // let's approximate... 33% overhead, ~= 3/8 (0.375)
    StringBuilder sb = new StringBuilder(inputEnd + (inputEnd >> 2) + (inputEnd >> 3));
    if (addQuotes) {
        sb.append('"');
    }
    int chunksBeforeLF = variant.getMaxLineLength() >> 2;
    int inputPtr = 0;
    while (inputPtr < inputEnd) {
        int count = Math.min(3, inputEnd - inputPtr);
        CharTypes.appendBase64Group(variant, sb, ByteArrayBuilder.packGroup(input, inputPtr, count), count);
        inputPtr += count;
        if (count == 3 && --chunksBeforeLF <= 0) {
            sb.append('\\');
            sb.append('n');
            chunksBeforeLF = variant.getMaxLineLength() >> 2;
        }
    }
    if (addQuotes) {
        sb.append('"');
    }
    return sb.toString();
