/**
 * Packs one group of one to three bytes, read from given array, into the
 * low 24 bits of an int, in big-endian order: the layout that
 * {@link #appendThreeBytes} writes out, and the one base64 encoding consumes.
 *<p>
 * Bytes are read from index {@code offset} on. Each byte is taken as an
 * unsigned octet (0 to 255): the first byte occupies bits 16 to 23, the
 * second bits 8 to 15 and the third bits 0 to 7. Positions of bytes beyond
 * {@code count} are zero, and bits 24 to 31 are always zero, so the result is
 * always between 0 and 0xFFFFFF, inclusive.
 *
 * @param data Array to read bytes from
 * @param offset Index of the first byte of the group
 * @param count Number of bytes in the group: 1, 2 or 3
 *
 * @return Group value, between 0 and 0xFFFFFF
 */
public static int packGroup(byte[] data, int offset, int count)
{
    int bits = 0;
    for (int i = 0; i < 3; ++i) {
        bits <<= 8;
        if (i < count) {
            bits |= data[offset + i] & 0xFF;
        }
    }
    return bits;
}

/**
 * Appends the base64 characters of one group of input bytes, using alphabet
 * and padding settings of given variant.
 *<p>
 * Group value {@code bits} must be laid out as {@link
 * com.fasterxml.jackson.core.util.ByteArrayBuilder#packGroup} returns it: a
 * value between 0 and 0xFFFFFF with the first byte in bits 16 to 23.
 * If {@code byteCount} is 3, the four characters produced by
 * {@link Base64Variant#encodeBase64Chunk(StringBuilder, int)} are appended;
 * if it is 1 or 2, the characters produced by
 * {@link Base64Variant#encodeBase64Partial(StringBuilder, int, int)} are
 * appended (two or three characters, plus padding if the variant uses it).
 * Nothing else (no linefeeds or quotes) is appended.
 *
 * @param variant Variant whose alphabet and padding are used
 * @param sb Builder to append characters to
 * @param bits Group value, between 0 and 0xFFFFFF
 * @param byteCount Number of bytes in the group: 1, 2 or 3
 */
public static void appendBase64Group(Base64Variant variant, StringBuilder sb, int bits, int byteCount)
{
    if (byteCount == 3) {
        variant.encodeBase64Chunk(sb, bits);
    } else {
        variant.encodeBase64Partial(sb, bits, byteCount);
    }
}

